      { auteur: "L'auteur d'aṭ-Ṭirāz ; Abū Bakr aṭ-Ṭurṭūshī", avis: "Ils retiennent la pureté retrouvée.", statut: "non_precise" },
      { auteur: "Ibn al-Fākihānī (commentaire de la Risāla)", avis: "Elle reste comme l'urine, son statut ne change pas : c'est le mashhūr ; de même si l'on en ôte une partie et que ses qualités redeviennent saines.", statut: "mashhur" }
